const webhookData = $('Webhook Clientes').first().json;
const clientes = webhookData.body?.clientes || webhookData.body || [];
const csvText = $input.first().json.data || '';

const lines = csvText.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim());

const produtos = [];
for (let i = 1; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  const values = line.split(',').map(v => v.trim());
  const prod = {};
  headers.forEach((h, idx) => {
    prod[h] = values[idx];
  });
  produtos.push(prod);
}

const results = [];
for (const cliente of clientes) {
  const opcoesRecomendadas = produtos.filter(
    p => p.perfil.toLowerCase() === (cliente.perfil || '').toLowerCase()
  );

  const resumoOpcoes = opcoesRecomendadas.map(
    p => `- ${p.produto} (Aplicação mínima: R$ ${p.minimo}, Rentabilidade: ${p.rentabilidade})`
  ).join('\n');

  const mensagemEstatica = `Olá ${cliente.nome}!\nIdentificamos que seu perfil de investidor é ${cliente.perfil} e seu saldo atual é de ${cliente.saldo}.\n\nCom base no seu perfil, recomendamos as seguintes opções de investimento:\n${resumoOpcoes}\n\nBons investimentos!`;

  const promptIA = `Você é um consultor financeiro e assistente de investimentos especializado do banco digital.\nCrie uma mensagem amigável, acolhedora, profissional e personalizada para o cliente abaixo:\n\n- Nome: ${cliente.nome}\n- Email: ${cliente.email}\n- Saldo Disponível: ${cliente.saldo}\n- Perfil de Investidor: ${cliente.perfil}\n\nOpções de investimento disponíveis no catálogo para este perfil:\n${resumoOpcoes}\n\nDiretrizes da mensagem:\n1. Cumprimente o cliente pelo primeiro nome.\n2. Reconheça o perfil (${cliente.perfil}) e o saldo disponível (${cliente.saldo}).\n3. Destaque quais das opções acima são mais recomendadas considerando o valor mínimo de aplicação em relação ao saldo dele.\n4. Explique brevemente o benefício principal da recomendação de forma clara, sem jargões excessivos.\n5. Finalize com uma chamada para ação convidando o cliente a entrar em contato ou confirmar a aplicação no aplicativo.\n6. Mantenha o tom profissional, humanizado e direto (máximo de 3 a 4 parágrafos curtos).`;

  results.push({
    json: {
      cliente: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      opcoesRecomendadas,
      mensagemEstatica,
      promptIA
    }
  });
}

return results;

const clientesData = $('Cruzar Clientes e Investimentos').all();
const geminiData = $input.all();

const relatorio = clientesData.map((c, i) => {
  const aiText = geminiData[i]?.json?.content?.parts?.[0]?.text || '';
  return {
    cliente: c.json.cliente,
    email: c.json.email,
    perfil: c.json.perfil,
    saldo: c.json.saldo,
    recomendacao_ia: aiText,
    mensagem_estatica_mvp: c.json.mensagemEstatica,
    opcoes_produtos: c.json.opcoesRecomendadas
  };
});

return [{
  json: {
    status: 'sucesso',
    total_processados: relatorio.length,
    timestamp: new Date().toISOString(),
    clientes: relatorio
  }
}];
